 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v)
    frames = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                     if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in perimeter):
            frames.append((color, r0, r1, c0, c1))

    # The frame's interior is filled with its paired scattered color on the
    # even checkerboard squares; the scattered marks are removed.
    out = [[0] * w for _ in range(h)]
    used_fill = set()
    for border, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = border if r in (r0, r1) or c in (c0, c1) else 0
        area = (r1 - r0 - 1) * (c1 - c0 - 1)
        needed = area // 2
        candidates = [color for color in range(1, 10)
                      if color != border and color not in {f[0] for f in frames}
                      and color not in used_fill and counts[color] == needed]
        if len(candidates) == 1:
            fill = candidates[0]
            used_fill.add(fill)
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == 0:
                        out[r][c] = fill
    return out
